"""F-16C cockpit geometry (wave 6 rebuild). Pure numpy; build.py turns the parts into Blender objects.

Output of build(): dict part key -> MeshData (drawing-frame verts converted to Blender, faces, uvs, name=key)
  'art:<panel>'  faces that look along the panel normal, UV = panel coords -> build/art/<panel>.png
  'm:<material>' everything else (constant colour; UVs are generated by the bake step)
  keys ending in '|lite' hold the faces that also go into the light stand-in (interior_lite)
screens: dict screen_* -> MeshData (UV 0..1), glass: dict name -> MeshData (transparent parts)
"""
import math
import numpy as np
from f16_geom import MeshData, to_blender
import f16_ck_layout as CL
import f16_cockpit_layout as OLD          # seat hip / back angle shared with the pilot figure
import f16_parts as PT
import f16_fuselage as FU

TAU = 2 * math.pi


def V3(*a):
    return np.array(a, float)


class Parts:
    def __init__(self):
        self.parts = {}
        self.screens = {}
        self.glass = {}

    def _md(self, key):
        return self.parts.setdefault(key, dict(v=[], f=[], uv=[]))

    def add(self, key, verts, faces, uvs=None, lite=False):
        """verts: (N,3) drawing frame; faces: list of index tuples; uvs: per-face list of (u,v) or None."""
        k = key + ('|lite' if lite else '')
        m = self._md(k)
        off = sum(len(x) for x in m['v'])
        m['v'].append(np.asarray(verts, float).reshape(-1, 3))
        for i, f in enumerate(faces):
            m['f'].append(tuple(int(j) + off for j in f))
            m['uv'].append(uvs[i] if uvs is not None else [(0.0, 0.0)] * len(f))

    def meshdata(self):
        out = {}
        for k, m in self.parts.items():
            if not m['f']:
                continue
            V = np.concatenate(m['v'])
            out[k] = MeshData(to_blender(V[:, 0], V[:, 1], V[:, 2]), m['f'], m['uv'], k)
        return out


def _single(verts, faces, uvs, name):
    V = np.asarray(verts, float)
    return MeshData(to_blender(V[:, 0], V[:, 1], V[:, 2]), faces, uvs, name)


# ----------------------------------------------------------------------------------------------------------------------
# local primitive generators: return (V (N,3), faces). Coordinates are "local" (x, y, z) in whatever frame the caller uses.
def g_box(x0, y0, z0, x1, y1, z1):
    V = [(x, y, z) for z in (z0, z1) for y in (y0, y1) for x in (x0, x1)]
    # index = zi*4 + yi*2 + xi
    F = [(0, 2, 3, 1), (4, 5, 7, 6), (0, 1, 5, 4), (2, 6, 7, 3), (0, 4, 6, 2), (1, 3, 7, 5)]
    return np.array(V, float), F


def g_cyl(r0, r1, z0, z1, n=16, cap0=True, cap1=True, x=0.0, y=0.0, rot=0.0):
    V = []
    for z, r in ((z0, r0), (z1, r1)):
        for k in range(n):
            a = TAU * k / n + rot
            V.append((x + r * math.cos(a), y + r * math.sin(a), z))
    F = [(k, (k + 1) % n, n + (k + 1) % n, n + k) for k in range(n)]
    if cap0:
        F.append(tuple(range(n))[::-1])
    if cap1:
        F.append(tuple(range(n, 2 * n)))
    return np.array(V, float), F


def g_lathe(profile, n=16, x=0.0, y=0.0, cap_top=True):
    """profile: list of (r, z) from bottom to top; revolve about local z at (x, y)."""
    V = []
    for r, z in profile:
        for k in range(n):
            a = TAU * k / n
            V.append((x + r * math.cos(a), y + r * math.sin(a), z))
    F = []
    m = len(profile)
    for i in range(m - 1):
        for k in range(n):
            a, b = i * n + k, i * n + (k + 1) % n
            F.append((a, b, b + n, a + n))
    if cap_top and profile[-1][0] > 1e-6:
        F.append(tuple(range((m - 1) * n, m * n)))
    return np.array(V, float), F


def g_fluted(r, z0, z1, flutes=18, depth=0.12, x=0.0, y=0.0, top_chamfer=0.25):
    """Fluted knob: star-shaped prism with a chamfered top."""
    n = flutes * 2
    V = []
    rings = [(z0, 1.0), (z1 - r * top_chamfer * 0.6, 1.0), (z1, 1.0 - top_chamfer)]
    for z, s in rings:
        for k in range(n):
            a = TAU * k / n
            rr = r * s * (1.0 if k % 2 == 0 else 1.0 - depth)
            V.append((x + rr * math.cos(a), y + rr * math.sin(a), z))
    F = []
    for i in range(len(rings) - 1):
        for k in range(n):
            a, b = i * n + k, i * n + (k + 1) % n
            F.append((a, b, b + n, a + n))
    F.append(tuple(range(2 * n, 3 * n)))
    return np.array(V, float), F


def g_tube(path, r, n=10, closed=False, caps=True):
    """Sweep a circle of radius r (scalar or per-point list) along a polyline (N,3)."""
    P = np.asarray(path, float)
    N = len(P)
    rs = np.full(N, r) if np.isscalar(r) else np.asarray(r, float)
    T = np.zeros_like(P)
    for i in range(N):
        if closed:
            T[i] = P[(i + 1) % N] - P[(i - 1) % N]
        else:
            T[i] = P[min(i + 1, N - 1)] - P[max(i - 1, 0)]
        T[i] /= np.linalg.norm(T[i]) + 1e-12
    ref = np.array([0, 0, 1.0]) if abs(T[0][2]) < 0.9 else np.array([1.0, 0, 0])
    U = []
    u = np.cross(T[0], ref); u /= np.linalg.norm(u)
    for i in range(N):
        u = u - T[i] * np.dot(u, T[i]); u /= np.linalg.norm(u) + 1e-12
        U.append(u.copy())
    V = []
    for i in range(N):
        w = np.cross(T[i], U[i])
        for k in range(n):
            a = TAU * k / n
            V.append(P[i] + rs[i] * (math.cos(a) * U[i] + math.sin(a) * w))
    F = []
    segs = N if closed else N - 1
    for i in range(segs):
        i2 = (i + 1) % N
        for k in range(n):
            a, b = i * n + k, i * n + (k + 1) % n
            F.append((a, b, i2 * n + (k + 1) % n, i2 * n + k))
    if caps and not closed:
        F.append(tuple(range(n))[::-1])
        F.append(tuple(range((N - 1) * n, N * n)))
    return np.array(V, float), F


def g_rrect_prism(w, h, r, z0, z1, n=4, x=0.0, y=0.0):
    """Rounded-rectangle prism (bezels, key caps)."""
    pts = []
    r = min(r, w / 2 - 1e-5, h / 2 - 1e-5)
    for cx, cy, a0 in ((w / 2 - r, h / 2 - r, 0), (-w / 2 + r, h / 2 - r, 90), (-w / 2 + r, -h / 2 + r, 180), (w / 2 - r, -h / 2 + r, 270)):
        for k in range(n + 1):
            a = math.radians(a0 + 90 * k / n)
            pts.append((x + cx + r * math.cos(a), y + cy + r * math.sin(a)))
    m = len(pts)
    V = [(px, py, z0) for px, py in pts] + [(px, py, z1) for px, py in pts]
    F = [(k, (k + 1) % m, m + (k + 1) % m, m + k) for k in range(m)]
    F.append(tuple(range(m))[::-1])
    F.append(tuple(range(m, 2 * m)))
    return np.array(V, float), F


def g_flange(dia, sw, sh, z0, z1, depth_cup, n=32, x=0.0, y=0.0):
    """Square instrument flange (sw x sh) with a round hole of diameter dia and an inner cup wall back to z0-depth_cup."""
    r = dia / 2
    V, F = [], []
    ring_in, ring_out = [], []
    for k in range(n):
        a = TAU * k / n
        c, s = math.cos(a), math.sin(a)
        # ray to the rectangle
        tx = (sw / 2) / abs(c) if abs(c) > 1e-9 else 1e9
        ty = (sh / 2) / abs(s) if abs(s) > 1e-9 else 1e9
        t = min(tx, ty)
        ring_in.append((x + r * c, y + r * s))
        ring_out.append((x + t * c, y + t * s))
    # front face (z1): quads between inner circle and outer square
    for (px, py) in ring_in:
        V.append((px, py, z1))
    for (px, py) in ring_out:
        V.append((px, py, z1))
    for k in range(n):
        k2 = (k + 1) % n
        F.append((k, k2, n + k2, n + k))
    # outer side walls (z0..z1)
    base = len(V)
    for (px, py) in ring_out:
        V.append((px, py, z0))
    for k in range(n):
        k2 = (k + 1) % n
        F.append((n + k, n + k2, base + k2, base + k))
    # inner cup wall (z1 .. z0 - depth_cup)
    base2 = len(V)
    for (px, py) in ring_in:
        V.append((px, py, z0 - depth_cup))
    for k in range(n):
        k2 = (k + 1) % n
        F.append((k2, k, base2 + k, base2 + k2))
    F = [tuple(f)[::-1] for f in F]
    return np.array(V, float), F


def g_rect_ring(ow, oh, iw, ih, z0, z1, well, n=64, x=0.0, y=0.0, p_out=7.0):
    """Display bezel: rounded outer rectangle (superellipse) with a rectangular window, plus the window's well walls
    back to z1 - well. Faces oriented: front +z, outer walls outward, well walls inward."""
    def sup(a, b, t, p):
        c, s_ = math.cos(t), math.sin(t)
        r = (abs(c / a) ** p + abs(s_ / b) ** p) ** (-1.0 / p)
        return r * c, r * s_
    V, F = [], []
    for k in range(n):
        t = TAU * k / n
        ix, iy = sup(iw / 2, ih / 2, t, 60.0)
        ox, oy = sup(ow / 2, oh / 2, t, p_out)
        V += [(x + ix, y + iy, z1), (x + ox, y + oy, z1), (x + ox, y + oy, z0), (x + ix, y + iy, z1 - well)]
    for k in range(n):
        a, b = 4 * k, 4 * ((k + 1) % n)
        F.append((a, b, b + 1, a + 1))          # front ring
        F.append((a + 1, b + 1, b + 2, a + 2))  # outer wall
        F.append((a + 3, b + 3, b, a))          # well wall
    V = np.array(V, float)
    out = []
    cen = np.array([x, y, 0.0])
    for i, f in enumerate(F):
        P = V[list(f)]
        nrm = face_normal(P)
        kind = i % 3
        if kind == 0:
            ok = nrm[2] > 0
        else:
            rad = P.mean(0) - cen; rad[2] = 0
            ok = np.dot(nrm, rad) > 0 if kind == 1 else np.dot(nrm, rad) < 0
        out.append(tuple(f) if ok else tuple(f)[::-1])
    return V, out


def g_torus_arc(R, r, a0, a1, n_major=16, n_minor=8, x=0.0, y=0.0, z=0.0):
    V = []
    for i in range(n_major + 1):
        a = a0 + (a1 - a0) * i / n_major
        cx, cy = x + R * math.cos(a), y + R * math.sin(a)
        for k in range(n_minor):
            b = TAU * k / n_minor
            rr = R + r * math.cos(b)
            V.append((x + rr * math.cos(a), y + rr * math.sin(a), z + r * math.sin(b)))
    F = []
    for i in range(n_major):
        for k in range(n_minor):
            a, b = i * n_minor + k, i * n_minor + (k + 1) % n_minor
            F.append((a, b, b + n_minor, a + n_minor))
    return np.array(V, float), F


def face_normal(P):
    n = np.zeros(3)
    for i in range(len(P)):
        a, b = P[i], P[(i + 1) % len(P)]
        n += np.cross(a, b)
    l = np.linalg.norm(n)
    return n / l if l > 1e-15 else n


def orient_out(V, F, center=None):
    """Flip faces so their normals point away from the centroid (closed convex-ish shapes)."""
    V = np.asarray(V, float)
    c = V.mean(0) if center is None else np.asarray(center, float)
    out = []
    for f in F:
        P = V[list(f)]
        if np.dot(face_normal(P), P.mean(0) - c) < 0:
            f = tuple(f)[::-1]
        out.append(tuple(f))
    return out


# ----------------------------------------------------------------------------------------------------------------------
class PanelCtx:
    """Adds item geometry in panel-local coords (x=u, y=v, z=d toward the pilot) to the parts, routing faces."""

    def __init__(self, parts, P):
        self.parts = parts
        self.P = P
        self.f = P['f']
        self.w, self.h = P['w'], P['h']
        self.art = 'art:' + P['name']
        self.lite = P.get('lite', True)
        M = np.array([self.f.u, self.f.v, self.f.n], float)      # rows
        self.M = M
        self.c = np.array(self.f.c, float)

    def uv(self, x, y):
        return ((x + self.w / 2) / self.w, (y + self.h / 2) / self.h)

    def to_world(self, V):
        V = np.asarray(V, float)
        return self.c + V @ self.M

    def add(self, V, F, mat, art_front=True, lite=False, thr=0.96, orient=True, center=None):
        V = np.asarray(V, float)
        if orient:
            F = orient_out(V, F, center)
        W = self.to_world(V)
        art_f, art_uv, oth_f = [], [], []
        for f in F:
            P = V[list(f)]
            nz = face_normal(P)[2]
            if art_front and nz > thr:
                art_f.append(f)
                art_uv.append([self.uv(V[i][0], V[i][1]) for i in f])
            else:
                oth_f.append(f)
        if art_f:
            self.parts.add(self.art, W, art_f, art_uv, lite=lite)
        if oth_f:
            self.parts.add('m:' + mat, W, oth_f, None, lite=lite)


# ----------------------------------------------------------------------------------------------------------------------
def build_panel(parts, P):
    ctx = PanelCtx(parts, P)
    w, h = P['w'], P['h']
    # face (outline polygon or rect), as a small grid for nicer baking
    outline = P['outline'] or [(-w / 2, -h / 2), (w / 2, -h / 2), (w / 2, h / 2), (-w / 2, h / 2)]
    V = [(x, y, 0.0) for x, y in outline]
    cen = np.mean(np.array(outline), 0)
    Vf = V + [(cen[0], cen[1], 0.0)]
    m = len(outline)
    F = [(k, (k + 1) % m, m) for k in range(m)]
    uvs = [[ctx.uv(Vf[i][0], Vf[i][1]) for i in f] for f in F]
    parts.add(ctx.art, ctx.to_world(Vf), F, uvs, lite=ctx.lite)
    # back skirt (panel thickness) down to -depth
    d = P['depth']
    Vs = [(x, y, 0.0) for x, y in outline] + [(x, y, -d) for x, y in outline]
    Fs = [((k + 1) % m, k, m + k, m + (k + 1) % m) for k in range(m)]
    parts.add('m:' + P.get('base', 'panel'), ctx.to_world(Vs), Fs, None, lite=ctx.lite)
    for it in P['items']:
        ITEM_BUILDERS.get(it['k'], lambda c, i: None)(ctx, it)
    return ctx


def it_gauge(ctx, it):
    x, y, dia = it['u'], it['v'], it['dia']
    if it['flange'] == 'tall':
        sw, sh = dia + 0.006, dia * 2.9
        V, F = g_rrect_prism(sw, sh, 0.003, 0.0, 0.006, x=x, y=y)
        ctx.add(V, F, 'black')
        return
    sw = sh = dia + 0.006
    V, F = g_flange(dia, sw, sh, 0.0, 0.007, 0.0, n=36, x=x, y=y)
    ctx.add(V, F, 'black', orient=False)
    ctx.parts.glass.setdefault('gauge_glass', []).append(
        ctx.to_world(np.array([(x + dia / 2 * math.cos(TAU * k / 24), y + dia / 2 * math.sin(TAU * k / 24), 0.0045) for k in range(24)])))
    kn = it.get('knob')
    if kn:
        where, r = kn
        pos = []
        if where in ('ll', 'both'):
            pos.append((x - sw / 2 + r * 0.9, y - sh / 2 + r * 0.9))
        if where in ('lr', 'both'):
            pos.append((x + sw / 2 - r * 0.9, y - sh / 2 + r * 0.9))
        for px, py in pos:
            V, F = g_fluted(r, 0.006, 0.017, flutes=14, x=px, y=py)
            ctx.add(V, F, 'black', orient=False)


def it_key(ctx, it):
    x, y, w, h = it['u'], it['v'], it['w'], it['h']
    d = it['depth']
    if it['style'] == 'round':
        # recessed collar + round cap
        V, F = g_cyl(w / 2 + 0.0015, w / 2 + 0.0015, 0.0, d * 0.5, n=20, cap0=False, x=x, y=y)
        ctx.add(V, F, 'black', art_front=False)
        V, F = g_cyl(w / 2 * 0.86, w / 2 * 0.86, 0.0, d, n=20, cap0=False, x=x, y=y)
        ctx.add(V, F, 'rubber', orient=False)
        return
    V, F = g_rrect_prism(w, h, min(w, h) * 0.12, 0.0, d, n=2, x=x, y=y)
    ctx.add(V, F, 'rubber', orient=False)


def it_light(ctx, it):
    x, y, w, h = it['u'], it['v'], it['w'], it['h']
    V, F = g_rrect_prism(w + 0.002, h + 0.002, 0.001, 0.0, it['depth'], n=1, x=x, y=y)
    ctx.add(V, F, 'black', orient=False)


def it_knob(ctx, it):
    x, y, r = it['u'], it['v'], it['r']
    st = it['style']
    if st == 'bar':
        # skirt + pointer bar knob ("chicken head")
        V, F = g_cyl(r * 1.05, r * 1.05, 0.0, 0.004, n=20, cap0=False, x=x, y=y)
        ctx.add(V, F, 'black', orient=False)
        V, F = g_box(-r * 1.25, -r * 0.33, 0.004, r * 1.25, r * 0.33, 0.004 + r * 1.3)
        a = math.radians(it.get('ang', 0.0) + 90)
        R = np.array([[math.cos(a), -math.sin(a), 0], [math.sin(a), math.cos(a), 0], [0, 0, 1]])
        V = V @ R.T + np.array([x, y, 0])
        ctx.add(V, F, 'black')
        return
    if st == 'wheelv':
        # vertical thumbwheel (pitch trim) in a slot
        V, F = g_box(x - r * 0.9, y - r * 1.4, 0.0, x + r * 0.9, y + r * 1.4, 0.002)
        ctx.add(V, F, 'black')
        V, F = g_cyl(r, r, -r * 0.45, r * 0.45, n=24, x=0.0, y=0.0)
        V = V[:, [2, 0, 1]] + np.array([x, y, 0.001])     # axis along u
        ctx.add(V, F, 'metal', art_front=False)
        return
    V, F = g_fluted(r, 0.0, it.get('h', 0.014) * (r / 0.01) ** 0.5, flutes=16, x=x, y=y)
    ctx.add(V, F, 'black', orient=False)


def it_toggle(ctx, it):
    x, y, s = it['u'], it['v'], it['size']
    # hex nut + bushing
    V, F = g_cyl(0.0042 * s, 0.0042 * s, 0.0, 0.0022 * s, n=6, cap0=False, x=x, y=y, rot=math.pi / 6)
    ctx.add(V, F, 'metal', orient=False)
    V, F = g_cyl(0.0026 * s, 0.0026 * s, 0.0022 * s, 0.0045 * s, n=10, cap0=False, x=x, y=y)
    ctx.add(V, F, 'metal', art_front=False, orient=False)
    ang = {'up': 22, 'dn': -22, 'mid': 0}[it['pos']]
    a = math.radians(ang)
    L = 0.017 * s
    p0 = np.array([x, y, 0.004 * s])
    dirv = np.array([0.0, math.sin(a), math.cos(a)])
    p1 = p0 + dirv * L
    V, F = g_tube([p0, p0 + dirv * L * 0.5, p1], [0.0012 * s, 0.0014 * s, 0.0019 * s], n=8)
    ctx.add(V, F, 'metal', art_front=False, orient=False)
    V, F = g_lathe([(0.0, -0.0022 * s), (0.0019 * s, -0.0012 * s), (0.0022 * s, 0.0), (0.0019 * s, 0.0012 * s), (0.0, 0.0022 * s)], n=10)
    # orient the tip ball along dirv
    V = V + p1
    ctx.add(V, F, 'metal', art_front=False, orient=False)
    g = it.get('guard')
    if g:
        # hinged cover (closed over the switch, open side toward the pilot's reach): U-shaped box
        col = 'red' if g == 'red' else 'yellow'
        gw, gh, gd = 0.014 * s, 0.026 * s, 0.022 * s
        yb = y + (0.002 if ang >= 0 else -0.002)
        for sx in (-1, 1):
            V, F = g_box(x + sx * gw / 2 - 0.0008, yb - gh / 2, 0.0, x + sx * gw / 2 + 0.0008, yb + gh / 2, gd)
            ctx.add(V, F, col, art_front=False)
        V, F = g_box(x - gw / 2 - 0.0008, yb - gh / 2, gd - 0.0016, x + gw / 2 + 0.0008, yb + gh / 2, gd)
        ctx.add(V, F, col, art_front=False)
        V, F = g_box(x - gw / 2 - 0.0008, yb + gh / 2 - 0.0016, 0.0, x + gw / 2 + 0.0008, yb + gh / 2, gd)
        ctx.add(V, F, col, art_front=False)


def it_display(ctx, it):
    x, y = it['u'], it['v']
    bw, bh, sw, sh, d = it['bw'], it['bh'], it['sw'], it['sh'], it['depth']
    sx, sy = x + it['soff'][0], y + it['soff'][1]
    ds = d - 0.004
    # bezel = frame around the display window (front face painted), window well 4 mm deep
    V, F = g_rect_ring(bw, bh, sw + 0.004, sh + 0.004, 0.0, d, 0.004, n=72, x=x, y=y)
    ctx.add(V, F, 'black', orient=False, lite=True)
    # back of the well (behind the screen) so the display never shows a hole
    Vb, Fb = g_box(sx - sw / 2 - 0.002, sy - sh / 2 - 0.002, 0.0, sx + sw / 2 + 0.002, sy + sh / 2 + 0.002, ds - 0.0005)
    ctx.add(Vb, Fb, 'black', art_front=False, lite=True)
    # screen quad (UV v = 1 at the bottom: glTF flips v and the avionics canvas textures keep flipY = true)
    Vs = [(sx - sw / 2, sy - sh / 2, ds), (sx + sw / 2, sy - sh / 2, ds), (sx + sw / 2, sy + sh / 2, ds), (sx - sw / 2, sy + sh / 2, ds)]
    ctx.parts.screens[it['name']] = _single(ctx.to_world(Vs), [(0, 1, 2, 3)], [[(0, 1), (1, 1), (1, 0), (0, 0)]], it['name'])
    if it['osb']:
        for bx, by, kw, kh in CL.osb_positions(it):
            V, F = g_rrect_prism(kw, kh, 0.0012, d, d + 0.0035, n=1, x=bx, y=by)
            ctx.add(V, F, 'rubber', orient=False)
        # rocker switches in the corners (GAIN / SYM / BRT / CON)
        for cx, cy in ((-1, 1), (1, 1), (-1, -1), (1, -1)):
            bx, by = x + cx * (bw / 2 - 0.0095), y + cy * (bh / 2 - 0.0095)
            V, F = g_rrect_prism(0.0085, 0.0085, 0.002, d, d + 0.003, n=1, x=bx, y=by)
            ctx.add(V, F, 'rubber', orient=False)


def it_wheel(ctx, it):
    x, y, r, w = it['u'], it['v'], it['r'], it['w']
    # ribbed thumbwheel, axis along v, half sunk into the face
    V, F = g_cyl(r, r, -w / 2, w / 2, n=28)
    V = V[:, [0, 2, 1]]                  # axis -> y
    V[:, 0] += x
    V[:, 1] += y
    V[:, 2] += -r * 0.35
    ctx.add(V, F, 'lgray', art_front=False)


def it_special(ctx, it):
    fn = SPECIALS.get(it['name'])
    if fn:
        fn(ctx, it)


ITEM_BUILDERS = dict(gauge=it_gauge, key=it_key, light=it_light, knob=it_knob, toggle=it_toggle, display=it_display,
                     wheel=it_wheel, special=it_special)


