# structure (drawing frame)
COCKPIT_C = np.array((4.15, 0.0, 2.35))


def add_world(parts, key, V, F, lite=False, orient=True, center=None, toward=None):
    """orient: faces point away from the centroid (closed convex solids); toward: faces point toward a point (sheets)."""
    V = np.asarray(V, float)
    if toward is not None:
        T = np.asarray(toward, float)
        out = []
        for f in F:
            P = V[list(f)]
            out.append(tuple(f) if np.dot(face_normal(P), T - P.mean(0)) >= 0 else tuple(f)[::-1])
        F = out
    elif orient:
        F = orient_out(V, F, center)
    parts.add('m:' + key, V, F, None, lite=lite)


def grid_faces(nr, nc):
    return [(i * nc + j, i * nc + j + 1, (i + 1) * nc + j + 1, (i + 1) * nc + j) for i in range(nr - 1) for j in range(nc - 1)]


def canopy_upper(s, y):
    """Height of the canopy glass (upper branch of its section) at station s, |y| (drawing frame)."""
    pts = np.asarray(PT.canopy_section(s, n=(10, 10, 6)))
    w = pts[:, 0]
    k = int(np.argmax(w))
    up = pts[:k + 1]
    return float(np.interp(abs(y), up[:, 0], up[:, 1]))


def build_glareshield(parts):
    """Anti-glare hood: top surface from the rear lip to the windscreen (flat over the ICP / RWR / DED, sloping
    'eyebrow' shoulders down to the canopy sills - the pilot's-view outline of the F-16C glareshield), lip fascia."""
    ne, nt = 41, 14
    S_FRONT = 3.12
    V = []
    for i in range(nt):
        t = i / (nt - 1)
        for j in range(ne):
            eta = -1 + 2 * j / (ne - 1)
            w = CL.LIP_W * (1 - t) + 0.318 * t
            y = eta * w
            s0 = CL.lip_s(y)
            s = s0 + t * (S_FRONT - s0)
            zc = CL.LIP_Z - 0.30 * t * (CL.LIP_S + CL.ICP_PROUD - S_FRONT)
            fl = CL.LIP_FLAT * (1 - t) + 0.13 * t
            z = zc - (zc - CL.SILL_Z + 0.02 * (1 - t)) * CL.lip_profile(y, fl, w)
            # keep 3 cm inside the canopy glass
            z = min(z, canopy_upper(s, y) - 0.03)
            V.append((s, y, z))
    F = grid_faces(nt, ne)
    Vn = np.array(V)
    F = [f if face_normal(Vn[list(f)])[2] > 0 else f[::-1] for f in F]
    parts.add('m:glare', Vn, F, None, lite=True)
    # lip fascia: 18 mm band under the lip, facing the pilot
    top = Vn[:ne]
    bot = top + np.array([0.004, 0.0, -0.018])
    Vf = np.concatenate([top, bot])
    Ff = [(j, j + 1, ne + j + 1, ne + j) for j in range(ne - 1)]
    Ff = [f if face_normal(Vf[list(f)])[0] > 0 else f[::-1] for f in Ff]
    parts.add('m:glare', Vf, Ff, None, lite=True)
    # underside back toward the bulkhead (hidden) so the hood looks solid from the sides
    under = bot + np.array([-0.10, 0.0, 0.0])
    Vu = np.concatenate([bot, under])
    Fu = [(j, j + 1, ne + j + 1, ne + j) for j in range(ne - 1)]
    Fu = [f if face_normal(Vu[list(f)])[2] < 0 else f[::-1] for f in Fu]
    parts.add('m:panel', Vu, Fu, None)


def build_hud(parts):
    """HUD combiner assembly on the glareshield (side frames, top bar, glass) + indexers + HUD camera."""
    yf = 0.115                   # side frames
    zt = 2.872                   # top bar
    s_rear = 3.642
    s_fb, z_fb = 3.470, CL.glare_top_z(3.470) + 0.004       # front-bottom of the glass
    s_ft = 3.598                 # front-top
    for sg in (-1, 1):
        y = sg * yf
        # rear post: tapered box
        V = [(s_rear - 0.024, y - 0.005, CL.glare_top_z(s_rear - 0.024) - 0.01), (s_rear, y - 0.005, CL.LIP_Z - 0.01),
             (s_rear, y - 0.005, zt), (s_rear - 0.014, y - 0.005, zt),
             (s_rear - 0.024, y + 0.005, CL.glare_top_z(s_rear - 0.024) - 0.01), (s_rear, y + 0.005, CL.LIP_Z - 0.01),
             (s_rear, y + 0.005, zt), (s_rear - 0.014, y + 0.005, zt)]
        F = [(0, 1, 2, 3), (4, 7, 6, 5), (0, 4, 5, 1), (1, 5, 6, 2), (2, 6, 7, 3), (3, 7, 4, 0)]
        add_world(parts, 'hudframe', V, F, lite=True)
        # front bar (glass edge frame)
        Vt, Ft = g_tube([(s_fb, y, z_fb), (s_ft, y, zt - 0.004)], 0.0032, n=8)
        add_world(parts, 'hudframe', Vt, Ft, lite=True, orient=False)
        # lower side plate between the front bar foot and the rear post (solid base)
        V = [(s_fb, y - 0.006, z_fb - 0.01), (s_rear - 0.03, y - 0.006, CL.glare_top_z(s_rear - 0.03) - 0.01),
             (s_rear - 0.03, y - 0.006, CL.glare_top_z(s_rear - 0.03) + 0.045), (s_fb + 0.02, y - 0.006, z_fb + 0.035),
             (s_fb, y + 0.006, z_fb - 0.01), (s_rear - 0.03, y + 0.006, CL.glare_top_z(s_rear - 0.03) - 0.01),
             (s_rear - 0.03, y + 0.006, CL.glare_top_z(s_rear - 0.03) + 0.045), (s_fb + 0.02, y + 0.006, z_fb + 0.035)]
        add_world(parts, 'hudframe', V, F, lite=True)
    # top bar (slightly arched)
    pts = [(s_rear - 0.012, t * yf * 1.02, zt + 0.010 * (1 - t * t)) for t in np.linspace(-1, 1, 9)]
    Vt, Ft = g_tube(pts, 0.0045, n=8)
    add_world(parts, 'hudframe', Vt, Ft, lite=True, orient=False)
    Vt, Ft = g_tube([(s_ft, -yf, zt - 0.004), (s_ft, yf, zt - 0.004)], 0.003, n=8)
    add_world(parts, 'hudframe', Vt, Ft, lite=True, orient=False)
    # combiner glass (tinted plate between the front bars)
    g = [(s_fb, -yf + 0.004, z_fb), (s_fb, yf - 0.004, z_fb), (s_ft, yf - 0.004, zt - 0.004), (s_ft, -yf + 0.004, zt - 0.004)]
    parts.glass.setdefault('hud_glass', []).append(np.array(g))
    # base box of the HUD between the frames (dark) sitting on the glareshield
    V, F = g_box(s_fb - 0.01, -yf, 0.0, s_rear - 0.03, yf, 1.0)
    V = np.array([(p[0], p[1], CL.glare_top_z(p[0]) - 0.02 + (0.012 if p[2] > 0.5 else 0.0)) for p in V])
    add_world(parts, 'hudframe', V, F, lite=True)
    # screen_hud: vertical quad at s_scr spanning +5.5 .. -15 deg, +-9.5 deg from the eye
    E = CL.EYE
    s_scr = 3.545
    dist = E[0] - s_scr
    zt_s = E[2] + dist * math.tan(math.radians(5.5))
    zb_s = E[2] - dist * math.tan(math.radians(15.0))
    hw = dist * math.tan(math.radians(9.3))
    Vs = [(s_scr, -hw, zb_s), (s_scr, hw, zb_s), (s_scr, hw, zt_s), (s_scr, -hw, zt_s)]
    parts.screens['screen_hud'] = _single(Vs, [(0, 1, 2, 3)], [[(0, 1), (1, 1), (1, 0), (0, 0)]], 'screen_hud')
    # AOA indexer (left) and AR status indexer (right): small boxes on the glareshield next to the combiner
    for sg in (-1, 1):
        y = sg * 0.150
        s0 = 3.625
        zb = CL.glare_top_z(s0 - 0.015) - 0.006
        V, F = g_box(s0 - 0.030, y - 0.012, zb, s0, y + 0.012, zb + 0.070)
        add_world(parts, 'hudframe', V, F, lite=True)
        for k in range(3):
            Vc, Fc = g_cyl(0.0048, 0.0048, 0.0, 0.004, n=12)
            Vc = Vc[:, [2, 0, 1]] + np.array([s0, y, zb + 0.056 - k * 0.018])
            add_world(parts, 'lens_' + ('amber' if k == 0 else 'green' if k == 1 else 'red'), Vc, Fc)
    # HUD camera (forward right of the combiner base)
    Vc, Fc = g_cyl(0.011, 0.011, 0.0, 0.055, n=16)
    Vc = Vc[:, [2, 0, 1]] * np.array([-1, 1, 1]) + np.array([3.530, 0.060, CL.glare_top_z(3.53) + 0.014])
    add_world(parts, 'hudframe', Vc, Fc)


def build_structure(parts):
    """Bulkhead behind the panels, ICP housing, pedestal, knee wells, floor, side walls, sill rails, pedals."""
    Z0 = CL.FLOOR_Z
    C = COCKPIT_C
    # forward bulkhead behind the panels (closes every gap between the panel planes); top follows the glareshield lip
    ys = np.linspace(-0.405, 0.405, 25)
    top = [(3.63, y, CL.lip_z(y) - 0.02) for y in ys]
    bot = [(3.63, y, Z0) for y in ys]
    Vb = np.array(bot + top)
    n = len(ys)
    add_world(parts, 'panel', Vb, [(i, i + 1, n + i + 1, n + i) for i in range(n - 1)], toward=(4.2, 0, 2.3))
    # ICP housing underside: from the ICP bottom edge back to the column top
    icp = CL.PANELS['icp']['f']; cs = CL.PANELS['cstack']['f']
    hw, hh = CL.ICP_W / 2, CL.ICP_H / 2
    a0 = icp.p(-hw, -hh); a1 = icp.p(hw, -hh)
    b0 = cs.p(-0.10, 0.16); b1 = cs.p(0.10, 0.16)
    add_world(parts, 'panel', [a0, a1, b1, b0], [(0, 1, 2, 3)], lite=True, toward=(4.3, 0, 2.2))
    # ICP housing side walls back into the glareshield
    for sg in (-1, 1):
        p = [icp.p(sg * hw, hh), icp.p(sg * hw, -hh), cs.p(sg * 0.10, 0.16),
             (3.60, sg * hw, 2.46), (3.60, sg * hw, 2.64)]
        add_world(parts, 'panel', p, [(0, 1, 2, 3, 4)], lite=True, toward=(3.7, sg * 0.4, 2.55))
    # center pedestal below the column down to the floor (between the knees)
    b0 = cs.p(-0.10, -0.16); b1 = cs.p(0.10, -0.16)
    PS = 3.70           # the pedestal's foot (station) - it slopes forward so the seat and ejection handle clear it
    V = [b0, b1, (PS, 0.07, Z0 + 0.12), (PS, -0.07, Z0 + 0.12)]
    add_world(parts, 'panel', V, [(0, 1, 2, 3)], lite=True, toward=(4.3, 0, 2.3))
    for sg in (-1, 1):
        bb = b1 if sg > 0 else b0
        V = [bb, (PS, sg * 0.07, Z0 + 0.12), (3.63, sg * 0.07, Z0 + 0.12), (3.63, sg * 0.10, bb[2])]
        add_world(parts, 'panel', V, [(0, 1, 2, 3)], toward=(3.75, sg * 0.3, 2.1))
    # recorder / standby compass box at the foot of the center column (dark box with a round lens housing)
    b0v, b1v = np.array(b0), np.array(b1)
    top = (b0v + b1v) / 2
    foot = np.array((PS, 0.0, Z0 + 0.12))
    vdir = (top - foot) / np.linalg.norm(top - foot)
    nrm = np.cross(np.array((0.0, 1.0, 0.0)), vdir); nrm /= np.linalg.norm(nrm)
    if nrm[0] < 0:
        nrm = -nrm
    A = np.array([(0.0, 1.0, 0.0), vdir, nrm])
    c0 = top - vdir * 0.055
    V, F = g_box(-0.034, -0.026, -0.03, 0.034, 0.026, 0.012)
    add_world(parts, 'black', c0 + V @ A, F)
    Vc, Fc = g_cyl(0.019, 0.017, 0.0, 0.016, n=24)
    add_world(parts, 'black', c0 + nrm * 0.012 + Vc @ A, Fc)
    Vc, Fc = g_cyl(0.013, 0.013, 0.0, 0.003, n=24)
    add_world(parts, 'lens_green', c0 + nrm * 0.027 + Vc @ A, Fc)
    # knee-well roofs under the MFD wings (dark)
    for sg in (-1, 1):
        mf = CL.PANELS['lmfd' if sg < 0 else 'rmfd']['f']
        a = mf.p(-0.08, -0.075); b = mf.p(0.08, -0.075)
        V = [a, b, (b[0] - 0.12, b[1], b[2] - 0.02), (a[0] - 0.12, a[1], a[2] - 0.02)]
        add_world(parts, 'panel', V, [(0, 1, 2, 3)], toward=(3.7, sg * 0.18, 2.0))
    # floor
    V = [(3.05, -0.36, Z0), (4.98, -0.36, Z0), (4.98, 0.36, Z0), (3.05, 0.36, Z0)]
    add_world(parts, 'floor', V, [(0, 1, 2, 3)], toward=(4.0, 0, 3.0))
    # footwell side walls forward of the consoles (floor -> sill)
    for sg in (-1, 1):
        V = [(3.10, sg * 0.34, Z0), (3.845, sg * 0.36, Z0), (3.845, sg * 0.405, CL.SILL_Z - 0.01), (3.10, sg * 0.33, CL.SILL_Z - 0.01)]
        add_world(parts, 'wall', V, [(0, 1, 2, 3)], toward=(3.5, 0, 2.2))
    for sg in (-1, 1):
        s0, s1, yi, yo, zt = CL.CONS_S0, CL.CONS_S1, CL.CONS_YI * sg, CL.CONS_YO * sg, CL.CONSOLE_Z
        # rounded console edge trim (inboard lip)
        Vt, Ft = g_tube([(s0, yi, zt - 0.004), (s1, yi, zt - 0.004)], 0.006, n=8)
        add_world(parts, 'panel', Vt, Ft, orient=False)
        # side wall above the console up to the sill
        S = np.linspace(3.845, 5.05, 14)
        top = [(s, sg * (min(PT.glass_edge_w(s) - 0.025, 0.405)), FU.surface_point(s, PT.glass_edge_w(s)) - 0.03) for s in S]
        bot = [(s, sg * min(PT.glass_edge_w(s) - 0.025, 0.405), zt if s <= s1 else Z0 + 0.25) for s in S]
        Vw = np.array(bot + top)
        n = len(S)
        add_world(parts, 'wall', Vw, [(i, i + 1, n + i + 1, n + i) for i in range(n - 1)], lite=True, toward=C)
        # aft of the console: the wall continues down to the floor
        Va = [(s1, sg * CL.CONS_YI, Z0), (4.95, sg * CL.CONS_YI, Z0), (4.95, sg * 0.40, Z0 + 0.25), (s1, sg * 0.404, Z0 + 0.25)]
        add_world(parts, 'wall', Va, [(0, 1, 2, 3)], toward=C)
        # canopy sill rail (longeron cap) with the seal: a rounded bar along the sill
        S2 = np.linspace(3.10, 5.10, 24)
        path = [(s, sg * (PT.glass_edge_w(s) - 0.028), FU.surface_point(s, PT.glass_edge_w(s)) - 0.018) for s in S2]
        Vt, Ft = g_tube(path, 0.014, n=10)
        add_world(parts, 'rail', Vt, Ft, lite=True, orient=False)
        seal = [(s, sg * (PT.glass_edge_w(s) - 0.014), FU.surface_point(s, PT.glass_edge_w(s)) - 0.004) for s in S2]
        Vt, Ft = g_tube(seal, 0.005, n=6)
        add_world(parts, 'rubber', Vt, Ft, orient=False)
    V = [(4.95, -0.40, Z0), (4.95, 0.40, Z0), (4.95, 0.34, 2.62), (4.95, -0.34, 2.62)]
    add_world(parts, 'wall', V, [(0, 1, 2, 3)], toward=(4.0, 0, 2.4))
    # rudder pedals (under the panel)
    for sg in (-1, 1):
        y = sg * 0.12
        ax = ((1, 0, 0.35), (0, 1, 0), (-0.35, 0, 1))
        c = np.array((3.20, y, 2.04))
        V, F = g_box(-0.012, -0.045, -0.085, 0.012, 0.045, 0.085)
        A = np.array([np.array(a) / np.linalg.norm(a) for a in ax])
        add_world(parts, 'metal', c + V @ A, F)
        Vt, Ft = g_tube([(3.10, y, 1.96), (3.19, y, 2.03)], 0.011, n=8)
        add_world(parts, 'metal', Vt, Ft, orient=False)
    # canopy manual handle on the right wall, forward of the console
    s0 = 3.80
    y = 0.395
    Vt, Ft = g_tube([(s0, y, 2.33), (s0 + 0.01, y - 0.03, 2.33), (s0 + 0.13, y - 0.03, 2.34)], 0.007, n=10)
    add_world(parts, 'metal', Vt, Ft, orient=False)
    V, F = g_box(s0 - 0.02, y - 0.004, 2.30, s0 + 0.03, y + 0.004, 2.37)
    add_world(parts, 'metal', V, F)


# ----------------------------------------------------------------------------------------------------------------------
def _loft(sections, cap0=True, cap1=True):
    """sections: list of (N,3) rings with the same N. Returns V, F."""
    S = [np.asarray(s, float) for s in sections]
    n = len(S[0])
    V = np.concatenate(S)
    F = []
    for i in range(len(S) - 1):
        for k in range(n):
            a, b = i * n + k, i * n + (k + 1) % n
            F.append((a, b, b + n, a + n))
    if cap0:
        F.append(tuple(range(n))[::-1])
    if cap1:
        F.append(tuple(range((len(S) - 1) * n, len(S) * n)))
    return V, F


def _ellipse(c, ax1, ax2, r1, r2, n=16, sq=2.0):
    c = np.asarray(c, float); ax1 = np.asarray(ax1, float); ax2 = np.asarray(ax2, float)
    ax1 = ax1 / np.linalg.norm(ax1); ax2 = ax2 / np.linalg.norm(ax2)
    out = []
    for k in range(n):
        a = TAU * k / n
        ca, sa = math.cos(a), math.sin(a)
        # superellipse for a boxier grip section
        cx = math.copysign(abs(ca) ** (2 / sq), ca)
        sy = math.copysign(abs(sa) ** (2 / sq), sa)
        out.append(c + r1 * cx * ax1 + r2 * sy * ax2)
    return np.array(out)


def build_stick(parts):
    """F-16 force sidestick (right console): boot, grip with trigger, pickle button, hat switches."""
    s0, y0, z0 = CL.STICK['s'], CL.STICK['y'], CL.CONSOLE_Z + 0.012
    # boot
    Vb, Fb = g_lathe([(0.026, 0.0), (0.024, 0.010), (0.018, 0.022), (0.015, 0.030)], n=16)
    add_world(parts, 'rubber', Vb + np.array([s0 + 0.01, y0, z0]), Fb, lite=True, orient=False)
    # grip: sections along a slightly forward-leaning axis (the grip is canted ~ 12 deg forward, 8 deg inboard)
    axis_dir = np.array([-0.20, -0.09, 1.0]); axis_dir /= np.linalg.norm(axis_dir)
    fwd = np.array([-1.0, 0, 0]); fwd = fwd - axis_dir * np.dot(fwd, axis_dir); fwd /= np.linalg.norm(fwd)
    side = np.cross(axis_dir, fwd)
    base = np.array([s0 + 0.01, y0, z0 + 0.028])
    prof = [(0.000, 0.016, 0.014, 0.0), (0.015, 0.019, 0.016, 0.0), (0.035, 0.023, 0.018, 0.0), (0.060, 0.024, 0.019, 0.0),
            (0.085, 0.023, 0.019, 0.002), (0.100, 0.024, 0.019, 0.006), (0.112, 0.032, 0.021, 0.014), (0.126, 0.037, 0.022, 0.018),
            (0.140, 0.036, 0.021, 0.018), (0.150, 0.030, 0.018, 0.014), (0.156, 0.018, 0.012, 0.010)]
    secs = []
    for t, rf, rs, off in prof:
        c = base + axis_dir * t + fwd * off
        secs.append(_ellipse(c, fwd, side, rf, rs, n=18, sq=2.6))
    V, F = _loft(secs)
    add_world(parts, 'stick', V, F, lite=True, orient=False)
    top = base + axis_dir * 0.150
    # trigger (front, curved paddle)
    tp = [base + axis_dir * 0.108 + fwd * 0.036, base + axis_dir * 0.094 + fwd * 0.044, base + axis_dir * 0.078 + fwd * 0.040]
    Vt, Ft = g_tube(tp, 0.0045, n=8)
    add_world(parts, 'stick', Vt, Ft, orient=False)
    # pickle button (red) on top-left, trim hat, TMS / DMS hats
    def button(center, dirn, r, h, mat, n=12):
        dirn = np.asarray(dirn, float); dirn /= np.linalg.norm(dirn)
        Vc, Fc = g_cyl(r, r, 0.0, h, n=n)
        a = np.array([0, 0, 1.0]); vv = np.cross(a, dirn); sn = np.linalg.norm(vv); cs = np.dot(a, dirn)
        if sn < 1e-9:
            R = np.eye(3)
        else:
            k = vv / sn
            K = np.array([[0, -k[2], k[1]], [k[2], 0, -k[0]], [-k[1], k[0], 0]])
            R = np.eye(3) + sn * K + (1 - cs) * K @ K
        add_world(parts, mat, Vc @ R.T + center, Fc, orient=False)
    top = base + axis_dir * 0.152 + fwd * 0.012
    button(top + side * (-0.010) + fwd * 0.022, axis_dir + fwd * 0.3, 0.0055, 0.009, 'red')          # weapon release
    button(top + side * 0.006 + fwd * 0.004, axis_dir, 0.0068, 0.008, 'stickhat')                    # trim
    button(top + fwd * (-0.012) + side * (-0.004) - axis_dir * 0.008, -fwd + axis_dir * 0.7, 0.0055, 0.008, 'stickhat')   # TMS
    button(base + axis_dir * 0.112 + fwd * 0.006 + side * 0.020, side + axis_dir * 0.3, 0.0048, 0.007, 'stickhat')          # DMS
    button(base + axis_dir * 0.128 + side * (-0.024) + fwd * 0.002, -side, 0.005, 0.007, 'stickhat')
    # pinky / NWS button and paddle switch
    button(base + axis_dir * 0.040 + fwd * 0.024, fwd, 0.004, 0.006, 'stickhat')
    Vp, Fp = g_box(-0.004, -0.012, -0.002, 0.004, 0.012, 0.002)
    add_world(parts, 'metal', Vp + base + axis_dir * 0.020 + fwd * 0.030, Fp)
    # armrest behind the stick (padded, inboard)
    s1 = s0 + 0.075
    V, F = g_box(s1, y0 - 0.040, CL.CONSOLE_Z + 0.0, s1 + 0.17, y0 + 0.010, CL.CONSOLE_Z + 0.045)
    add_world(parts, 'cushion', V, F, lite=True)


def build_throttle(parts):
    """Throttle (left console): quadrant slot, lever, grip with HOTAS switches."""
    s0, y0 = CL.THROTTLE['s'], CL.THROTTLE['y']
    zt = CL.CONSOLE_Z
    # lever from the slot
    p0 = np.array([s0 + 0.025, y0, zt - 0.02])
    p1 = np.array([s0 + 0.005, y0 - 0.005, zt + 0.055])
    Vt, Ft = g_tube([p0, p1], 0.008, n=10)
    add_world(parts, 'metal', Vt, Ft, orient=False)
    # grip: a mouse-like body lying fore-aft (hand on top, fingers over the front), lofted along -s
    zb = p1[2] - 0.006
    prof = [  # (s offset from the lever top, half width, bottom z, top z)
        (0.050, 0.020, 0.006, 0.030), (0.035, 0.028, 0.000, 0.058), (0.015, 0.031, -0.004, 0.078), (-0.010, 0.032, -0.006, 0.090),
        (-0.035, 0.031, -0.004, 0.098), (-0.060, 0.029, 0.004, 0.104), (-0.080, 0.026, 0.016, 0.104), (-0.094, 0.020, 0.032, 0.094),
        (-0.101, 0.010, 0.050, 0.080)]
    secs = []
    for ds, hw, z0, z1 in prof:
        c = np.array([p1[0] + ds, p1[1] + 0.004, zb + (z0 + z1) / 2])
        secs.append(_ellipse(c, np.array([0, 0, 1.0]), np.array([0, 1.0, 0]), (z1 - z0) / 2, hw, n=20, sq=2.8))
    V, F = _loft(secs)
    add_world(parts, 'stick', V, F, lite=True, orient=False)
    fwd = np.array([-1.0, 0, 0]); up = np.array([0, 0, 1.0]); side = np.array([0, 1.0, 0])
    base = np.array([p1[0], p1[1] + 0.004, zb])

    def cylat(center, dirn, r, h, mat, n=12):
        dirn = np.asarray(dirn, float); dirn /= np.linalg.norm(dirn)
        Vc, Fc = g_cyl(r, r, 0.0, h, n=n)
        a = np.array([0, 0, 1.0]); vv = np.cross(a, dirn); sn = np.linalg.norm(vv); cs = np.dot(a, dirn)
        if sn < 1e-9:
            R = np.eye(3)
        else:
            k = vv / sn
            K = np.array([[0, -k[2], k[1]], [k[2], 0, -k[0]], [-k[1], k[0], 0]])
            R = np.eye(3) + sn * K + (1 - cs) * K @ K
        add_world(parts, mat, Vc @ R.T + center, Fc, orient=False)
    cylat(base + fwd * 0.078 + up * 0.100, fwd * 0.6 + up, 0.0085, 0.010, 'stickhat', n=16)          # MAN RNG / UNCAGE
    cylat(base + fwd * 0.055 + up * 0.104, up, 0.0055, 0.008, 'stickhat')                             # comm switch
    cylat(base + fwd * 0.090 + up * 0.080 + side * 0.012, fwd, 0.0075, 0.006, 'stickhat', n=16)       # antenna elevation
    cylat(base + fwd * 0.094 + up * 0.060 + side * 0.016, fwd, 0.0042, 0.008, 'stickhat')             # dogfight
    cylat(base + fwd * 0.050 + up * 0.060 + side * 0.031, side, 0.0055, 0.007, 'stickhat')            # cursor enable/slew
    cylat(base + fwd * 0.030 + up * 0.080 + side * 0.030, side, 0.0045, 0.006, 'stickhat')            # speed brake
    cylat(base + fwd * 0.080 + up * 0.030 + side * 0.020, fwd, 0.004, 0.010, 'stickhat')              # black-out switch
    # quadrant slot rails
    L0, L1 = CL.THROTTLE['slot']
    for dy in (-0.012, 0.012):
        V, F = g_box(L0, y0 + dy - 0.002, zt, L1, y0 + dy + 0.002, zt + 0.006)
        add_world(parts, 'black', V, F)


def build_seat(parts):
    """ACES II ejection seat (reclined 30 deg): bucket, back, headbox + drogue/pitots, cushions, harness, ejection handle."""
    hs, _, hz = OLD.SEAT_HIP
    ang = OLD.SEAT_BACK
    up = np.array((math.sin(ang), 0.0, math.cos(ang)))
    fwd = np.array((-math.cos(ang), 0.0, math.sin(ang)))
    side = np.array((0.0, 1.0, 0.0))
    H = np.array((hs, 0.0, hz))

    def obox(mat, c, size, axes, lite=False):
        A = np.array([np.asarray(a, float) / np.linalg.norm(a) for a in axes])
        V, F = g_box(-size[0] / 2, -size[1] / 2, -size[2] / 2, size[0] / 2, size[1] / 2, size[2] / 2)
        add_world(parts, mat, np.asarray(c) + V @ A, F, lite=lite)

    BA = (fwd, side, up)
    # back structure + back cushion (with vertical quilting via 3 pads)
    obox('seatframe', H + up * 0.40 - fwd * 0.095, (0.05, 0.46, 0.82), BA, lite=True)
    for k, yy in enumerate((-0.12, 0.0, 0.12)):
        obox('cushion', H + up * 0.33 - fwd * 0.045 + side * yy, (0.055, 0.115, 0.50), BA, lite=True)
    # headbox (parachute container) + headrest pad + canopy breakers
    obox('headbox', H + up * 0.74 - fwd * 0.125, (0.17, 0.43, 0.30), BA, lite=True)
    obox('cushion', H + up * 0.77 - fwd * 0.030, (0.06, 0.26, 0.17), BA, lite=True)
    obox('seatframe', H + up * 0.895 - fwd * 0.125, (0.18, 0.44, 0.02), BA, lite=True)
    for sg in (-1, 1):
        # canopy breakers / pitot booms on the headbox top
        p0 = H + up * 0.90 - fwd * 0.16 + side * sg * 0.17
        Vt, Ft = g_tube([p0, p0 + up * 0.11 + fwd * 0.03], 0.0055, n=8)
        add_world(parts, 'metal', Vt, Ft, orient=False)
        p0 = H + up * 0.90 - fwd * 0.09 + side * sg * 0.07
        Vt, Ft = g_tube([p0, p0 + up * 0.035], 0.012, n=10)
        add_world(parts, 'seatframe', Vt, Ft, orient=False)
        # side rails of the back (bucket extensions) and the guide rails behind
        obox('seatframe', H + up * 0.30 - fwd * 0.080 + side * sg * 0.222, (0.07, 0.028, 0.58), BA, lite=True)
        r0 = H + up * 0.02 - fwd * 0.18 + side * sg * 0.13
        Vt, Ft = g_tube([r0, r0 + up * 0.86], 0.013, n=8)
        add_world(parts, 'metal', Vt, Ft, orient=False)
        # shoulder harness straps from the headbox down the back cushion
        a = H + up * 0.62 - fwd * 0.012 + side * sg * 0.085
        c = H + up * 0.08 + fwd * 0.012 + side * sg * 0.105
        m = (a + c) / 2
        obox('strap', m, (0.006, 0.045, np.linalg.norm(a - c)), (fwd, side, a - c))
    # seat pan: survival kit + cushion, raised front
    pan = ((1, 0, -0.14), (0, 1, 0), (0.14, 0, 1))
    # (the pan ends ~10 cm short of the knees; the ejection handle sits just aft of the center pedestal)
    obox('seatframe', (hs - 0.055, 0, hz - 0.075), (0.36, 0.44, 0.11), pan, lite=True)
    obox('fur', (hs - 0.06, 0, hz - 0.005), (0.33, 0.38, 0.05), pan, lite=True)
    obox('kit', (hs - 0.08, 0, hz - 0.145), (0.26, 0.30, 0.05), pan)
    for sg in (-1, 1):
        obox('seatframe', (hs - 0.05, sg * 0.228, hz + 0.02), (0.36, 0.026, 0.21), ((1, 0, 0), (0, 1, 0), (0, 0, 1)), lite=True)
        obox('black', (hs - 0.14, sg * 0.232, hz + 0.135), (0.14, 0.032, 0.028), ((1, 0, 0), (0, 1, 0), (0, 0, 1)))
        # lap belt halves
        obox('strap', (hs - 0.08, sg * 0.14, hz + 0.05), (0.05, 0.12, 0.006), ((1, 0, 0.3), (0, 1, 0), (-0.3, 0, 1)))
    obox('metal', (hs - 0.09, 0, hz + 0.066), (0.06, 0.07, 0.014), ((1, 0, 0.3), (0, 1, 0), (-0.3, 0, 1)))
    # ejection handle: yellow/black striped loop at the front of the seat bucket
    pts = []
    R = 0.045
    cx, cz = hs - 0.225, hz + 0.03
    for k in range(25):
        a = math.pi * k / 24
        pts.append((cx - 0.012 * math.sin(a), -R * math.cos(a), cz + 0.05 * math.sin(a) ** 0.7))
    for k in range(len(pts) - 1):
        Vt, Ft = g_tube([pts[k], pts[k + 1]], 0.0075, n=8, caps=False)
        add_world(parts, 'yellow' if (k // 2) % 2 == 0 else 'black', Vt, Ft, orient=False)
    for sg in (-1, 1):
        Vt, Ft = g_tube([(cx, sg * R, cz), (cx + 0.03, sg * R, cz - 0.03)], 0.0075, n=8)
        add_world(parts, 'yellow', Vt, Ft, orient=False)
    # emergency manual chute handle (left side of the seat bucket) and shoulder harness lock (small ball knob)
    Vt, Ft = g_tube([(hs - 0.16, -0.245, hz + 0.08), (hs - 0.20, -0.245, hz + 0.10), (hs - 0.20, -0.245, hz + 0.05)], 0.006, n=8)
    add_world(parts, 'yellow', Vt, Ft, orient=False)
    Vs, Fs = g_lathe([(0.0, -0.01), (0.008, -0.006), (0.009, 0.0), (0.008, 0.006), (0.0, 0.01)], n=12)
    add_world(parts, 'black', Vs + np.array([hs - 0.15, -0.248, hz + 0.16]), Fs, orient=False)


# ----------------------------------------------------------------------------------------------------------------------
def build():
    CL.build_layout()
    parts = Parts()
    for name, P in CL.PANELS.items():
        build_panel(parts, P)
    build_glareshield(parts)
    build_hud(parts)
    build_structure(parts)
    build_stick(parts)
    build_throttle(parts)
    build_seat(parts)
    md = parts.meshdata()
    screens = parts.screens
    glass = {}
    for k, rings in parts.glass.items():
        V, F = [], []
        for r in rings:
            off = len(V)
            V.extend(list(r))
            F.append(tuple(range(off, off + len(r))))
        Vn = np.array(V)
        glass[k] = MeshData(to_blender(Vn[:, 0], Vn[:, 1], Vn[:, 2]), F, None, k)
    return md, screens, glass
